<script setup lang="ts">
import { computed, onBeforeUnmount, ref, shallowRef, watch } from 'vue'
import AppIcon from '../components/AppIcon.vue'
import DentalCanvas from './DentalCanvas.vue'
import DentalRadiograph from './DentalRadiograph.vue'
import catalog from '../../../contracts/dental/sources.v1.json'
import { measurementSeries, measurementTemplate, parseMeasurements, type DentalScan, type DentalView, type ImportedMeasurements } from './model'
defineProps<{reducedMotion:boolean}>()
const imageOpened=ref(false)
const tab=ref<'scans'|'images'|'measurements'|'sources'>('scans'),scan=shallowRef<DentalScan|null>(null),scanError=ref(''),scanLoading=ref(false),view=ref<DentalView>('front'),canvas=ref<InstanceType<typeof DentalCanvas>>()
watch(tab,value=>{if(value==='images')imageOpened.value=true})
const data=shallowRef<ImportedMeasurements|null>(null),subject=ref(''),metric=ref(''),tooth=ref<string>('none'),error=ref(''),loading=ref(false),filename=ref(''),rawText=ref(''),provenance=ref(''),fingerprint=ref('')
let scanToken=0,dataToken=0,disposed=false
const toothOptions=computed(()=>[...new Set(data.value?.rows.filter(r=>r.subject===subject.value&&r.metric===metric.value).map(r=>r.tooth===null?'none':String(r.tooth))??[])])
watch([data,subject,metric],()=>{if(!toothOptions.value.includes(tooth.value))tooth.value=toothOptions.value[0]??'none'})
const series=computed(()=>measurementSeries(data.value,subject.value,metric.value,tooth.value==='none'?null:Number(tooth.value)))
const graph=computed(()=>{const s=series.value;if(!s.length)return[];const minX=s[0]!.x,maxX=s.at(-1)!.x,minY=Math.min(...s.map(r=>r.value))-1,maxY=Math.max(...s.map(r=>r.value))+1;return s.map(r=>({x:maxX===minX?320:48+(r.x-minX)/(maxX-minX)*544,y:176-(r.value-minY)/(maxY-minY)*138,row:r}))})
const change=computed(()=>series.value.length>1?series.value.at(-1)!.value-series.value[0]!.value:null)
function download(text:string,name:string,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function acceptMeasurements(text:string,name:string,source:string){const token=++dataToken;loading.value=true;error.value='';try{const next=parseMeasurements(text,name.toLowerCase().endsWith('.json')?'json':'csv');const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text));if(disposed||token!==dataToken)return;data.value=next;subject.value=next.subjects[0]!;metric.value=next.metrics[0]!;tooth.value='none';filename.value=name;rawText.value=text;provenance.value=source;fingerprint.value=Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('')}catch(e){if(token===dataToken)error.value=e instanceof Error?e.message:'Could not import measurements.'}finally{if(token===dataToken)loading.value=false}}
async function loadGrowth(){const token=++dataToken;loading.value=true;try{const r=await fetch(`${import.meta.env.BASE_URL}data/dental/orthodont-growth.csv`);if(!r.ok)throw new Error('The reference CSV could not be loaded.');const text=await r.text();if(disposed||token!==dataToken)return;await acceptMeasurements(text,'orthodont-growth.csv','Published historical craniofacial growth data · R nlme / UNC Dental School')}catch(e){if(token===dataToken){error.value=e instanceof Error?e.message:'Reference data unavailable.';loading.value=false}}}
async function importMeasurements(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file)return;if(file.size>2000000||! /\.(csv|json)$/i.test(file.name)){error.value='Choose a CSV or JSON file up to 2 MB. Export Excel sheets as CSV first.';return}const token=++dataToken;loading.value=true;try{const text=await file.text();if(disposed||token!==dataToken)return;await acceptMeasurements(text,file.name,'Local measurement file · source and review supplied by you')}catch{if(token===dataToken){error.value='Could not read the measurement file.';loading.value=false}}}
async function loadReferenceScan(){const token=++scanToken;scanLoading.value=true;scanError.value='';try{const parts=await Promise.all(['upper','lower'].map(async jaw=>{const r=await fetch(`${import.meta.env.BASE_URL}data/dental/reference-${jaw}.stl`);if(!r.ok)throw new Error('Reference casts could not be loaded.');return{name:jaw,format:'stl' as const,bytes:await r.arrayBuffer()}}));if(disposed||token!==scanToken)return;scan.value={id:`reference-${token}`,name:'Published upper & lower dental casts',parts,source:'Abdi & Nouri (2020), Serial 3D Dental Models, Mendeley Data V1',license:'CC BY 4.0'};view.value='front'}catch(e){if(token===scanToken)scanError.value=e instanceof Error?e.message:'Scan unavailable.'}finally{if(token===scanToken)scanLoading.value=false}}
async function importScan(event:Event){const input=event.target as HTMLInputElement,files=Array.from(input.files??[]);input.value='';if(!files.length)return;const token=++scanToken;scanError.value='';if(files.length>2||files.some(f=>f.size>40000000||!/\.(stl|obj|glb)$/i.test(f.name))){scanError.value='Open one or two STL, OBJ or self-contained GLB files, each up to 40 MB.';return}scanLoading.value=true;try{const parts=await Promise.all(files.map(async f=>({name:f.name,format:f.name.split('.').at(-1)!.toLowerCase() as 'stl'|'obj'|'glb',bytes:await f.arrayBuffer()})));if(disposed||token!==scanToken)return;scan.value={id:`local-${token}`,name:files.map(f=>f.name).join(' + '),parts,source:'Local files · no upload',license:'Your supplied data permissions'};view.value='front'}catch{scanError.value='Could not read the selected files.'}finally{if(token===scanToken)scanLoading.value=false}}
onBeforeUnmount(()=>{disposed=true;scanToken++;dataToken++})
</script>
<template>
 <section class="dental-research panel"><div class="dental-research-tabs" role="group" aria-label="Research data type"><button v-for="item in (['scans','images','measurements','sources'] as const)" :key="item" :aria-pressed="tab===item" @click="tab=item"><AppIcon :name="({scans:'layers',images:'scan',measurements:'activity',sources:'book'})[item]" :size="17"/>{{ ({scans:'3D scans',images:'X-rays & images',measurements:'Measurements',sources:'Source library'})[item] }}</button></div>
 <div v-show="tab==='scans'" class="dental-data-body"><div class="dental-data-heading"><div><span class="dental-eyebrow">SURFACE GEOMETRY</span><h3>Real casts. Original detail.</h3><p>Inspect a published scan or your own upper and lower jaw files.</p></div><div class="dental-file-actions"><button class="button-secondary" :disabled="scanLoading" @click="loadReferenceScan">Load published casts</button><label class="button-primary dental-file-button"><AppIcon name="plus" :size="16"/>Open local 3D<input type="file" accept=".stl,.obj,.glb" multiple @change="importScan"/></label></div></div><p v-if="scanError" class="dental-error" role="alert">{{ scanError }}</p><p v-if="scanLoading" role="status">Reading scan surfaces…</p>
  <div v-if="scan" class="dental-scan-stage"><DentalCanvas v-if="tab==='scans'" ref="canvas" :view="view" :selected="11" appliance="none" elastic="#249e98" :opening="0" :reduced-motion="reducedMotion" :scan="scan" @error="scanError=$event"/><div class="dental-canvas-badge">RESEARCH SCAN <span>Unsegmented surface</span></div><div class="dental-stage-toolbar"><button @click="canvas?.reset()" aria-label="Reset scan view"><AppIcon name="reset" :size="16"/>Reset</button><button v-for="axis in (['x','y','z'] as const)" :key="axis" @click="canvas?.orient(axis)">Rotate {{ axis.toUpperCase() }} 90°</button></div></div>
  <div v-else class="dental-empty"><AppIcon name="layers" :size="42"/><h4>Bring your research into view.</h4><p>STL · OBJ · self-contained GLB. A pair retains its original shared coordinates. The published example contains normal-occlusion plaster casts.</p><button class="dental-text-button" @click="loadReferenceScan">Explore the reference pair <AppIcon name="arrowRight" :size="16"/></button></div>
  <div v-if="scan" class="dental-scan-provenance"><strong>{{ scan.name }}</strong><p>{{ scan.source }} · {{ scan.license }}</p><p class="dental-small">Original units are fit to the screen. These surfaces have no tooth labels; tooth picking and braces are available in the teaching atlas. No scan segmentation or clinical measurements are inferred.</p><button class="dental-text-button" @click="scan=null;scanError=''">Close scan</button></div><a class="dental-source-link" href="https://data.mendeley.com/datasets/bpnmf2vhsk/1" target="_blank" rel="noopener noreferrer">Original serial casts · source and license ↗</a>
 </div>
 <div v-if="imageOpened" v-show="tab==='images'" class="dental-data-body"><DentalRadiograph/></div>
 <div v-show="tab==='measurements'" class="dental-data-body"><div class="dental-data-heading"><div><span class="dental-eyebrow">LONGITUDINAL RECORDS</span><h3>One subject. Every observation.</h3><p>Keep measurements separated by subject, metric, unit and tooth.</p></div><div class="dental-file-actions"><button class="button-secondary" :disabled="loading" @click="loadGrowth">Load 108 reference rows</button><label class="button-primary dental-file-button"><AppIcon name="plus" :size="16"/>Import CSV / JSON<input type="file" accept=".csv,.json" @change="importMeasurements"/></label></div></div><p v-if="error" class="dental-error" role="alert">{{ error }}</p><p v-if="loading" role="status">Validating measurements…</p>
 <div v-if="data" class="dental-measurements"><div class="dental-import-status"><AppIcon name="check" :size="17"/><span>{{ data.rows.length }} measurements · {{ data.subjects.length }} coded subjects</span><button class="dental-text-button" @click="data=null;rawText='';fingerprint='';loading=false;dataToken++">Clear data</button></div><p class="dental-small">{{ provenance }}</p><div class="dental-data-filters"><label class="dental-field">Subject<select v-model="subject" aria-label="Measurement subject"><option v-for="s in data.subjects" :key="s">{{ s }}</option></select></label><label class="dental-field">Metric<select v-model="metric" aria-label="Measurement metric"><option v-for="m in data.metrics" :key="m" :value="m">{{ m.replaceAll('_',' ') }}</option></select></label><label class="dental-field">Tooth<select v-model="tooth" aria-label="Measurement tooth"><option v-for="t in toothOptions" :key="t" :value="t">{{ t==='none'?'No tooth specified':`FDI ${t}` }}</option></select></label></div>
 <div class="dental-observation-stats"><div><span>Observations</span><strong>{{ series.length }}</strong></div><div><span>Latest measurement</span><strong>{{ series.at(-1)?.value??'—' }} <small>{{ series.at(-1)?.unit }}</small></strong></div><div><span>Change from first</span><strong>{{ change===null?'—':`${change>0?'+':''}${Number(change.toFixed(3))}` }} <small v-if="change!==null">{{ series[0]?.unit }}</small></strong></div></div>
 <figure class="dental-observation-chart"><svg viewBox="0 0 640 220" role="img" :aria-label="`${subject}, ${metric}: ${series.map(r=>`${r.xLabel}: ${r.value} ${r.unit}`).join('; ')}`"><path d="M48 30V184H602" fill="none" stroke="#cbdcda"/><path v-for="y in [50,95,140]" :key="y" :d="`M48 ${y}H602`" stroke="#e8efed"/><polyline :points="graph.map(p=>`${p.x},${p.y}`).join(' ')" fill="none" stroke="#18867c" stroke-width="2.5"/><g v-for="(p,i) in graph" :key="i"><circle :cx="p.x" :cy="p.y" r="5" fill="#18867c" stroke="white" stroke-width="2"/><text :x="p.x" :y="p.y-13" text-anchor="middle">{{ p.row.value }}</text><text :x="p.x" y="207" text-anchor="middle" v-if="graph.length<9||i===0||i===graph.length-1">{{ p.row.xLabel }}</text></g><text x="48" y="18">{{ metric.replaceAll('_',' ') }} · {{ series[0]?.unit }}</text></svg><figcaption>Observed values only. Lines connect observations; they do not predict treatment or imply clinical improvement.</figcaption></figure>
 <div class="dental-table-scroll"><table><thead><tr><th>Observation</th><th>Value</th><th>Unit</th><th>Source row</th></tr></thead><tbody><tr v-for="r in series" :key="r.sourceRow"><td>{{ r.xLabel }}</td><td>{{ r.value }}</td><td>{{ r.unit }}</td><td>{{ r.sourceRow }}</td></tr></tbody></table></div><div class="dental-data-footer"><button class="button-secondary" @click="download(rawText,filename,filename.endsWith('.json')?'application/json':'text/csv')"><AppIcon name="download" :size="16"/>Export original data</button><span :title="fingerprint">SHA-256 {{ fingerprint.slice(0,16) }}…</span></div></div>
 <div v-else class="dental-empty"><AppIcon name="activity" :size="42"/><h4>Follow the measured change.</h4><p>Load the historical growth series or import coded study records. Excel sheets can be exported as CSV.</p><button class="dental-text-button" @click="download(measurementTemplate,'dental-measurements-template.csv','text/csv')">Download CSV template <AppIcon name="download" :size="16"/></button></div>
 <details class="dental-import-schema"><summary>Measurement format and validation</summary><p>CSV headers or JSON object fields: <code>subject_id, recorded_at, tooth_fdi, metric, value, unit</code>. Use coded IDs, ISO dates, a permanent FDI tooth or blank, a metric identifier and numeric values. Units: mm, degrees, score or hours. Duplicate observations and mixed units for one metric are rejected. R’s Orthodont format is also supported.</p><p>The growth reference measures skull landmarks over childhood. It contains no treatment outcome or brace prescription.</p></details></div>
 <div v-if="tab==='sources'" class="dental-data-body"><div class="dental-data-heading"><div><span class="dental-eyebrow">VERIFIED RESEARCH SOURCES · 05 NOV 2026</span><h3>Start with traceable data.</h3><p>Primary dataset releases, access conditions and limits for your research.</p></div></div><div class="dental-source-grid"><article v-for="d in catalog.datasets" :key="d.id" class="dental-dataset-card"><span class="dental-source-type">{{ d.modality }}</span><h4>{{ d.title }}</h4><p>{{ d.institution }}</p><strong>{{ d.scale }}</strong><span class="dental-license">{{ d.license }}</span><p>{{ d.access }}</p><p class="dental-small">{{ d.limitation }}</p><a :href="d.url" target="_blank" rel="noopener noreferrer">Open original dataset ↗</a></article></div><p class="dental-small">The bundled samples belong to independent published cohorts. They are not matched modalities from one patient. No training, segmentation or diagnostic model is running.</p></div>
 </section>
</template>
